// Some portions generated by Claude
/**
 * The Filters panel's repository values (repository-facets.ts) kept in IndexedDB for an hour, so opening the Graph
 * page again, or another tab of it, asks the repository nothing. Rows are keyed [namespace, revision, node]: the
 * namespace names the repository, graph scope and inference setting, the revision changes whenever the Workbench
 * writes to the repository (data-revision.ts). Rows of other revisions are deleted when a store opens.
 */
import type { FacetStorePersistence, StoredEntry } from "./repository-facets.ts";

export const FACET_VALUES_TTL_MS = 60 * 60 * 1000;
const DATABASE = "graph-field-facet-values";
const ENTRIES = "entries";
export const LABELS = "labels";

type Key = [string, string, string];
export type FacetRow<T = StoredEntry> = { key: Key; storedAt: number; entry: T };

/** Where rows live: IndexedDB in the browser, a Map in tests. */
export interface FacetBackend<T = StoredEntry> {
  get(keys: Key[]): Promise<Array<FacetRow<T> | undefined>>;
  put(rows: FacetRow<T>[]): Promise<void>;
  /** Deletes the namespace's rows of other revisions and those stored before `before`. */
  prune(namespace: string, revision: string, before: number): Promise<void>;
  /** Deletes all of the namespace's rows. */
  clear(namespace: string): Promise<void>;
}

/** The repository, graph scope and inference setting the values were read with. */
export function facetNamespace(repositoryScope: string, graphScope: string, inferred: boolean) {
  return JSON.stringify([repositoryScope, graphScope, inferred]);
}

export function facetPersistence(options: {
  backend: FacetBackend;
  baseNamespace: string;
  revision: string;
  now?: () => number;
  ttlMs?: number;
}): FacetStorePersistence & { ready: Promise<void> } {
  const { backend, baseNamespace: namespace, revision } = options;
  const now = options.now ?? Date.now;
  const ttl = options.ttlMs ?? FACET_VALUES_TTL_MS;
  const ready = backend.prune(namespace, revision, now() - ttl).catch(() => undefined);
  return {
    ready,
    async read(ids) {
      const found = new Map<string, StoredEntry>();
      try {
        const rows = await backend.get(ids.map((id) => [namespace, revision, id] as Key));
        const oldest = now() - ttl;
        rows.forEach((row, index) => {
          if (row && row.storedAt >= oldest) found.set(ids[index], row.entry);
        });
      } catch {
        // Storage that cannot be read is no storage: the repository is asked instead.
      }
      return found;
    },
    async write(entries) {
      const storedAt = now();
      await backend.put([...entries].map(([id, entry]) => ({ key: [namespace, revision, id] as Key, storedAt, entry })));
    },
    async clear() {
      await backend.clear(namespace);
    },
  };
}

export function memoryFacetBackend<T = StoredEntry>(): FacetBackend<T> & { size(): number } {
  const rows = new Map<string, FacetRow<T>>();
  const keyOf = (key: Key) => JSON.stringify(key);
  return {
    size: () => rows.size,
    async get(keys) {
      return keys.map((key) => rows.get(keyOf(key)));
    },
    async put(list) {
      list.forEach((row) => rows.set(keyOf(row.key), structuredClone(row)));
    },
    async prune(namespace, revision, before) {
      rows.forEach((row, key) => {
        if (row.key[0] === namespace && (row.key[1] !== revision || row.storedAt < before)) rows.delete(key);
      });
    },
    async clear(namespace) {
      rows.forEach((row, key) => {
        if (row.key[0] === namespace) rows.delete(key);
      });
    },
  };
}

let opened: Promise<IDBDatabase> | null = null;

/** The shared database; also holds the value labels (LABELS store). Null where IndexedDB is unavailable or blocked. */
export function facetDatabase(): Promise<IDBDatabase> | null {
  if (typeof indexedDB === "undefined") return null;
  opened ??= new Promise<IDBDatabase>((resolve, reject) => {
    const request = indexedDB.open(DATABASE, 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore(ENTRIES, { keyPath: "key" });
      request.result.createObjectStore(LABELS, { keyPath: "key" });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
    request.onblocked = () => reject(new Error("Filter value storage is blocked by another tab."));
  }).catch((error) => {
    opened = null;
    throw error;
  });
  return opened;
}

/** All rows whose key starts with the namespace: [namespace] sorts before every longer key, arrays after strings. */
export function namespaceRange(namespace: string) {
  return IDBKeyRange.bound([namespace], [namespace, []]);
}

function done(transaction: IDBTransaction) {
  return new Promise<void>((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onabort = () => reject(transaction.error);
    transaction.onerror = () => reject(transaction.error);
  });
}

export function indexedDbFacetBackend<T = StoredEntry>(storeName = ENTRIES): FacetBackend<T> {
  const withStore = async <T>(mode: IDBTransactionMode, work: (store: IDBObjectStore) => T) => {
    const database = await facetDatabase();
    if (!database) throw new Error("IndexedDB is unavailable.");
    const transaction = database.transaction(storeName, mode);
    const result = work(transaction.objectStore(storeName));
    await done(transaction);
    return result;
  };
  return {
    async get(keys) {
      const rows: Array<FacetRow<T> | undefined> = new Array(keys.length);
      await withStore("readonly", (store) =>
        keys.forEach((key, index) => {
          const request = store.get(key);
          request.onsuccess = () => (rows[index] = request.result as FacetRow<T> | undefined);
        }),
      );
      return rows;
    },
    async put(list) {
      if (!list.length) return;
      await withStore("readwrite", (store) => list.forEach((row) => store.put(row)));
    },
    async prune(namespace, revision, before) {
      await withStore("readwrite", (store) => {
        const cursor = store.openCursor(namespaceRange(namespace));
        cursor.onsuccess = () => {
          const current = cursor.result;
          if (!current) return;
          const row = current.value as FacetRow<T>;
          if (row.key[1] !== revision || row.storedAt < before) current.delete();
          current.continue();
        };
      });
    },
    async clear(namespace) {
      await withStore("readwrite", (store) => store.delete(namespaceRange(namespace)));
    },
  };
}
